//! The bundled mixin snapshot: kit descriptors from the mixins of
//! nikcio/docker-sandboxing, fetched at build time by `build.rs` and shipped
//! with the app so discovery has an offline fallback when GitHub rate limits
//! or connectivity block the live fetch.
//!
//! The snapshot lives under `target/snapshot/mixins` (see `bundle.resources`
//! in tauri.conf.json) and is loaded into memory before discovery; "refresh
//! bundled mixins" re-reads it without an app restart. The release list is
//! generated by `build.rs` from its `RELEASES` table.

include!(concat!(env!("OUT_DIR"), "/bundled_releases.rs"));

use std::collections::HashSet;
use std::path::Path;
use std::sync::{Arc, RwLock};

use serde_json::Value;

use super::descriptor::{comment_descriptor, option_from_descriptor};
use super::encoded;
use super::types::Catalog;

pub(super) const DEFAULT_PROVIDER_ID: &str = "nikcio-docker-sandboxing";
// REPOSITORY comes from the generated bundled_releases.rs include above.

/// One release's snapshot in memory: the repository-relative descriptor paths
/// and their text, mirroring the live GitHub tree layout.
#[derive(Default)]
pub(crate) struct Snapshot {
    pub(crate) files: Vec<(String, String)>,
}

static SNAPSHOT: RwLock<Option<Arc<Snapshot>>> = RwLock::new(None);

/// Read one release's mixins (`{tag}/{mixin}/spec.yaml`) from the bundle.
/// Unreadable or unparseable files are skipped: the snapshot is a fallback,
/// not a source of truth, and partial coverage still beats none.
pub(crate) fn load_snapshot(tag: &str, bundle: &Path) -> Snapshot {
    let mut files = Vec::new();
    let Ok(releases) = std::fs::read_dir(bundle.join(tag)) else {
        return Snapshot { files };
    };
    let mut mixins: Vec<_> = releases
        .filter_map(|entry| entry.ok())
        .filter(|entry| entry.file_type().is_ok_and(|t| t.is_dir()))
        .map(|entry| entry.file_name())
        .collect();
    mixins.sort();
    for mixin in mixins {
        let path = Path::new(tag).join(&mixin).join("spec.yaml");
        let Ok(text) = std::fs::read_to_string(bundle.join(&path)) else {
            continue;
        };
        let descriptor = comment_descriptor(&text).unwrap_or_else(|| text.clone());
        let Ok(value) = serde_yaml_ng::from_str::<Value>(&descriptor) else {
            continue;
        };
        if value["kind"].as_str() != Some("mixin") {
            continue;
        }
        files.push((path.to_string_lossy().into_owned(), text));
    }
    Snapshot { files }
}

/// Replace the in-memory snapshot; later catalog lookups see the new bundle.
pub(crate) fn store_snapshot(snapshots: Vec<Snapshot>) {
    let mut merged = Snapshot::default();
    for snapshot in snapshots {
        merged.files.extend(snapshot.files);
    }
    if let Ok(mut slot) = SNAPSHOT.write() {
        *slot = Some(Arc::new(merged));
    }
}

fn snapshot() -> Arc<Snapshot> {
    if let Ok(slot) = SNAPSHOT.read()
        && let Some(snapshot) = slot.as_ref()
    {
        return snapshot.clone();
    }
    // Nothing was loaded (the command layer failed to resolve the bundle, or a
    // test drives discovery directly): an empty snapshot only disables the
    // fallback, which the caller already handles.
    Arc::new(Snapshot::default())
}

/// Build the fallback catalog from the loaded snapshot. Rows are ordered
/// newest release first and a mixin name is only listed once, so the newest
/// bundled version of each mixin is the one offered — matching the live
/// discovery's newest-release-first tag order.
pub(super) fn bundled_catalog() -> Catalog {
    let snapshot = snapshot();
    let mut kits = Vec::new();
    let mut seen = HashSet::new();
    for (path, text) in &snapshot.files {
        let descriptor = comment_descriptor(text).unwrap_or_else(|| text.clone());
        let Ok(value) = serde_yaml_ng::from_str::<Value>(&descriptor) else {
            continue;
        };
        let tag = path.split('/').next().unwrap_or_default();
        let Some((_, commit)) = BUNDLED_RELEASES.iter().find(|(release, _)| *release == tag) else {
            continue;
        };
        let source = source(commit, path);
        // Paths are `{tag}/{mixin}/spec.yaml`, so the second component is the
        // mixin's identity, used as the fallback name for descriptors without
        // an authored one.
        let name = path.split('/').nth(1).unwrap_or(DEFAULT_PROVIDER_ID);
        let Ok(kit) = option_from_descriptor(&value, &source, DEFAULT_PROVIDER_ID, name) else {
            continue;
        };
        if seen.insert(kit.name.clone()) {
            kits.push(kit);
        }
    }
    kits.sort_by(|a, b| (&a.kind, &a.name, &a.source).cmp(&(&b.kind, &b.name, &b.source)));
    Catalog {
        kits,
        warnings: Vec::new(),
    }
}

/// Load the whole bundle (`resources/mixins`) into memory and report the
/// descriptor count, so the refresh command can report what the snapshot offers.
pub fn load_bundled_mixins(bundle: &Path) -> Result<usize, String> {
    if !bundle.is_dir() {
        return Err(format!(
            "Bundled mixin snapshot is missing: {}",
            bundle.display()
        ));
    }
    let snapshots: Vec<_> = BUNDLED_RELEASES
        .iter()
        .map(|(tag, _)| load_snapshot(tag, bundle))
        .collect();
    let count: usize = snapshots.iter().map(|s| s.files.len()).sum();
    store_snapshot(snapshots);
    Ok(count)
}

fn source(commit: &str, path: &str) -> String {
    // The bundle layout is `{tag}/{mixin}/spec.yaml` while the repository
    // layout is `mixins/{mixin}/spec.yaml`; the git source's dir fragment
    // must be repository-relative or sbx cannot load the kit at launch.
    let mixin = path.split('/').nth(1).unwrap_or_default();
    format!(
        "git+https://github.com/{REPOSITORY}.git#ref={}&dir={}",
        encoded(commit),
        encoded(&format!("mixins/{mixin}"))
    )
}
